def solve(tokens):
    """Evaluate Reverse Polish Notation expression (batch 2).
    tokens: list of strings containing integers or '+', '-', '*', '/'.
    Returns integer result with division truncating toward zero.
    """
    stack = []
    for tok in tokens:
        if tok in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division, truncate toward zero
                # Python int division truncates toward negative infinity, so use int(a / b)
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

