    """Evaluate Reverse Polish Notation expression.
    Supports +, -, *, / with integer division truncating toward zero.
    Returns 0 for empty input.
    """
    def div_trunc(a, b):
        # Truncate toward zero without converting to float
        if b == 0:
            raise ZeroDivisionError('division by zero')
        q = abs(a) // abs(b)
        return q if (a * b) >= 0 else -q

    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # '/'
                res = div_trunc(a, b)
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0
